/* Lafz service worker (generated by scripts/postbuild.mjs). Hand-rolled, no dependencies.
 * - App shell (pages, JS, CSS, fonts, icons) is precached on install, so the app opens offline.
 * - Navigations: network first, falling back to the cache (fresh content when online).
 * - Static assets: cache first.
 * - Audio: cached the first time it plays; "Download for offline" caches a whole unit.
 */
const VERSION = "__VERSION__";
const SHELL = __SHELL__;
const SHELL_CACHE = `lafz-shell-${VERSION}`;
const AUDIO_CACHE = "lafz-audio-v1";

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches.open(SHELL_CACHE).then(async (cache) => {
      // Add one by one so a single failure doesn't abort the install.
      await Promise.all(SHELL.map((url) => cache.add(url).catch(() => undefined)));
    }),
  );
  self.skipWaiting();
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith("lafz-shell-") && k !== SHELL_CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

const RSC_CACHE = "lafz-rsc-v1";

async function cacheFirst(req, cacheName) {
  const cache = await caches.open(cacheName);
  const hit = await cache.match(req);
  if (hit) return hit;
  const res = await fetch(req);
  if (res.ok && res.status === 200) cache.put(req, res.clone());
  return res;
}

/** HTML navigations: fresh when online, cached page (by path, never by query) when offline. */
async function navigate(req) {
  const url = new URL(req.url);
  const key = url.pathname.endsWith("/") ? url.pathname : `${url.pathname}/`;
  const cache = await caches.open(SHELL_CACHE);
  try {
    const res = await fetch(req);
    if (res.ok && (res.headers.get("content-type") || "").includes("text/html")) cache.put(key, res.clone());
    return res;
  } catch {
    return (await cache.match(key)) || (await caches.match(key)) || (await cache.match("/lafz/")) || Response.error();
  }
}

/** React Server Component payloads: exact-URL cache. A miss offline makes Next do a full page load. */
async function rsc(req) {
  const cache = await caches.open(RSC_CACHE);
  try {
    const res = await fetch(req);
    if (res.ok) cache.put(req, res.clone());
    return res;
  } catch {
    return (await cache.match(req)) || Response.error();
  }
}

self.addEventListener("fetch", (event) => {
  const req = event.request;
  if (req.method !== "GET") return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin || !url.pathname.startsWith("/lafz/")) return;
  if (url.pathname.startsWith("/lafz/audio/")) {
    // Range requests can't be answered from partial cache entries; always serve the whole file.
    event.respondWith(cacheFirst(new Request(url.pathname), AUDIO_CACHE));
  } else if (req.mode === "navigate") {
    event.respondWith(navigate(req));
  } else if (url.searchParams.has("_rsc") || req.headers.get("RSC") || url.pathname.endsWith(".txt")) {
    event.respondWith(rsc(req));
  } else if (url.pathname.startsWith("/lafz/offline/")) {
    event.respondWith(rsc(req));
  } else {
    event.respondWith(cacheFirst(req, SHELL_CACHE));
  }
});
